# wezterm shell integration for bash — OSC 133 semantic prompt markers.
# Source from ~/.bashrc:
#   [ -f ~/.config/wezterm/shell-integration.sh ] && . ~/.config/wezterm/shell-integration.sh
# No-op unless running inside a wezterm pane.
[ -n "${WEZTERM_PANE:-}" ] || return 0 2>/dev/null || exit 0

__wezterm_osc133() { printf '\033]133;%s\007' "$1"; }

__wezterm_precmd() {
    # D = previous command finished (exit status), A = new prompt started
    __wezterm_osc133 "D;$__wezterm_last_status"
    __wezterm_osc133 "A"
}

__wezterm_preexec() {
    # B = user input finished, C = command execution started
    __wezterm_osc133 "B"
    __wezterm_osc133 "C"
}

__wezterm_last_status=0
__wezterm_prompt_wrapper() {
    __wezterm_last_status=$?
    __wezterm_precmd
}

# preexec via DEBUG trap; skip when bash is just running PROMPT_COMMAND
__wezterm_debug_trap() {
    case "$BASH_COMMAND" in
        "$PROMPT_COMMAND") return 0 ;;
    esac
    __wezterm_preexec
}
trap '__wezterm_debug_trap' DEBUG

case ";${PROMPT_COMMAND};" in
    *";__wezterm_prompt_wrapper;"*) ;;
    *) PROMPT_COMMAND="__wezterm_prompt_wrapper${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
esac


