# ── first-class ffs search wrappers (replaces find/grep for agents) ────
find() {
  if [ $# -eq 0 ]; then
    ffs find .
  elif [ $# -eq 1 ] && [[ "$1" != -* ]]; then
    ffs find "$1"
  elif [[ "$*" == *"-name"* ]] || [[ "$*" == *"-type"* ]] || [[ "$*" == *"-exec"* ]]; then
    /usr/bin/fd "$@" 2>/dev/null || /usr/bin/find "$@"
  else
    ffs find "$@"
  fi
}
grep() {
  local _github=0
  local _clean=()
  while [ $# -gt 0 ]; do
    case "$1" in
      --github) _github=1; shift ;;
      -g) _github=1; shift ;;
      *) _clean+=("$1"); shift ;;
    esac
  done
  if [ "$_github" -eq 1 ]; then
    if [ ${#_clean[@]} -eq 0 ]; then
      printf 'Usage: grep --github <query> [flags]\n' >&2
      return 1
    fi
    gh search code "${_clean[@]}" 2>&1 | jq .
  else
    set -- "${_clean[@]}"
    local _args=()
    local _root="."
    local _pattern=""
    while [ $# -gt 0 ]; do
      case "$1" in
        -E) _args+=("--regex"); shift ;;
        -e) shift; _pattern="$1"; shift ;;
        -i) _args+=("--ignore-case"); shift ;;
        -F) _args+=("--fixed-strings"); shift ;;
        -r) shift; _root="$1"; shift ;;
        -l) _args+=("--files-with-matches"); shift ;;
        -w) _args+=("--word-regexp"); shift ;;
        -v) _args+=("--invert-match"); shift ;;
        -a) _args+=("--text"); shift ;;
        -C) _args+=("--context" "$2"); shift 2 ;;
        -A) _args+=("--after-context" "$2"); shift 2 ;;
        -B) _args+=("--before-context" "$2"); shift 2 ;;
        -m) _args+=("--max-count" "$2"); shift 2 ;;
        -o) _args+=("--only-matching"); shift ;;
        -s) _args+=("--case-sensitive"); shift ;;
        -g) _args+=("--glob" "$2"); shift 2 ;;
        --*) _args+=("$1"); shift ;;
        *)  if [ -z "$_pattern" ] && [ ! -f "$1" ]; then _pattern="$1"; elif [ -d "$1" ]; then _root="$1"; fi; shift ;;
      esac
    done
    if [ -z "$_pattern" ]; then
      printf 'Usage: grep [-EeirFvlwvoAaBCGmOsws] PATTERN [FILE...]\n' >&2
      return 1
    fi
    ffs grep "${_args[@]}" "$_pattern" --root "$_root"
  fi
}
